import os from 'os';
import ctx from 'ctx';

async function select({ id }) {
  // Choosing a block stops the replay and shows the block under the header (step-view): State changes first, or
  // Details when the block changed nothing. Choosing the shown block again hides it.
  const d = os.get('extension.views.timeline-view.ui-data'), R = os.refs['timeline-view'], sv = 'extension.views.step-view';
  d.playing = false;
  R.flow = null;
  if (d.selected === id && os.mounted(sv)) {
    d.selected = null;
    await ctx.call('extension.functions.unmount', { view_path: sv });
    return;
  }
  d.selected = id;
  os.get(sv + '.ui-data').tab = (R.changes || {})[id] ? 'state' : 'details';
  if (!os.mounted(sv)) await ctx.call('extension.functions.render', { view_path: sv });
}

local.next.code:
import os from 'os';
import ctx from 'ctx';

async function next({ delta }) {
  // Moves delta blocks, inside the flow that plays if there is one (the arrow buttons leave the flow). The replay
  // stops at the block that was the last when it started.
  const d = os.get('extension.views.timeline-view.ui-data'), R = os.refs['timeline-view'];
  if (R.flow && !d.playing) R.flow = null;
  const ids = R.flow ? R.flow.ids : R.steps;
  let at = ids.indexOf(d.selected);
  if (at < 0) at = R.flow ? -1 : ids.length - 1;
  const to = Math.max(0, Math.min(ids.length - 1, at + (+delta || 0)));
  d.selected = ids[to];
  if (to === ids.length - 1 || (d.playing && ids[to] === R.end)) d.playing = false;
  os.get('extension.views.step-view.ui-data').tab = (R.changes || {})[d.selected] ? 'state' : 'details';
  if (!os.mounted('extension.views.step-view')) await ctx.call('extension.functions.render', { view_path: 'extension.views.step-view' });
}

