local.play-flow.code:
import os from 'os';
import ctx from 'ctx';

async function playFlow({ name }) {
  // Plays a saved flow: its blocks, one after the other. A flow names its blocks; each is the first block with that
  // name after the block before it.
  const d = os.get('extension.views.timeline-view.ui-data'), R = os.refs['timeline-view'];
  const flow = d.flows.find(f => f.name === name);
  if (!flow) throw new Error('No flow ' + name + '. Flows: ' + d.flows.map(f => f.name).join(', '));
  const names = R.names || [], ids = [];
  let from = 0;
  flow.steps.forEach(n => {
    const at = names.indexOf(n, from);
    if (at >= 0) { ids.push(R.steps[at]); from = at + 1; }
  });
  if (!ids.length) throw new Error('None of the blocks of ' + name + ' is in the timeline.');
  R.flow = { name, ids };
  R.end = ids[ids.length - 1];
  d.flows_open = false;
  d.selected = ids[0];
  d.playing = ids.length > 1;
  os.get('extension.views.step-view.ui-data').tab = (R.changes || {})[d.selected] ? 'state' : 'details';
  if (!os.mounted('extension.views.step-view')) await ctx.call('extension.functions.render', { view_path: 'extension.views.step-view' });
  return { blocks: ids.length };
}

local.play.code:
import os from 'os';
import ctx from 'ctx';

async function play() {
  // Starts or stops the replay. From the last block, it starts again at the first. A paused flow goes on; after
  // the end of a flow, the replay is of all the blocks.
  const d = os.get('extension.views.timeline-view.ui-data'), R = os.refs['timeline-view'];
  if (R.flow && !d.playing && d.selected === R.flow.ids[R.flow.ids.length - 1]) R.flow = null;
  const ids = R.flow ? R.flow.ids : R.steps;
  d.playing = !d.playing;
  const at = ids.indexOf(d.selected);
  if (d.playing && (at < 0 || at === ids.length - 1)) d.selected = ids[0];
  // With the timeline tracked, each move adds a block: the replay ends at the block that is the last now.
  // Untracked, it goes on to the newest block: after a reload, the page is still starting when the replay starts.
  if (d.playing) R.end = d.track_timeline && !R.flow ? ids[ids.length - 1] : null;
  os.get('extension.views.step-view.ui-data').tab = (R.changes || {})[d.selected] ? 'state' : 'details';
  if (!os.mounted('extension.views.step-view')) await ctx.call('extension.functions.render', { view_path: 'extension.views.step-view' });
}

local.init.code:
import os from 'os';
import ctx from 'ctx';

async function init() {
  // The view of the chosen block draws itself after every call (local.refresh), and now.
  const R = os.refs['step-view'] = {}, v = 'extension.views.step-view';
  // Typing in the filter shows only the paths that have the text, like the filter of the state view; Escape clears it.
  const input = ctx.root.querySelector('#st-filter-input');
  input.addEventListener('input', () => {
    clearTimeout(R.filterTimer);
    R.filterTimer = setTimeout(() => os.call('local.filter', { text: input.value }, v).catch(console.error), 120);
  });
  input.addEventListener('keydown', e => {
    if (e.key !== 'Escape') return;
    input.value = '';
    os.call('local.filter', { text: '' }, v).catch(console.error);
  });
  os.watch(v, 'local.refresh');
  await ctx.call('local.refresh', { after: 'local.init' });
}

local.refresh.code:
import os from 'os';
import ctx from 'ctx';

async function refresh({ after }) {
  const v = 'extension.views.step-view', d = os.get(v + '.ui-data'), T = os.refs['timeline-view'];
  // The tabs are drawn again from ui-data.
  const tmp = document.createElement('div');
  tmp.innerHTML = os.template(os.get(v + '.html'), d);
  const tabs = tmp.querySelector('.tl-tabs');
  ctx.root.querySelector('.tl-tabs').replaceWith(tabs);
  os.bind(tabs, v);
  // The filter shows on State changes; its switches are drawn again (the input stays, so typing goes on).
  ctx.root.querySelector('#st-filter').hidden = d.tab !== 'state';
  const switches = tmp.querySelector('#st-switches');
  ctx.root.querySelector('#st-switches').replaceWith(switches);
  os.bind(switches, v);
  const input = ctx.root.querySelector('#st-filter-input');
  if (document.activeElement !== input && input.value !== d.filter) input.value = d.filter;
  const el = (tag, cls, text) => { const x = document.createElement(tag); if (cls) x.className = cls; if (text !== undefined) x.textContent = text; return x; };
  const title = ctx.root.querySelector('#st-title'), box = ctx.root.querySelector('#tl-detail');
  // The timeline keeps the chosen block and draws what is in it.
  const cur = T && T.current;
  if (!cur) { title.textContent = ''; box.textContent = 'Choose a block in the timeline.'; return; }
  const key = cur.id + ':' + d.tab, keep = T.shown === key ? box.scrollTop : 0;
  title.textContent = '';
  title.appendChild(el('span', 'tl-kind', cur.label));
  title.appendChild(el('span', 'tl-name', cur.name));
  title.appendChild(el('span', 'tl-time', (cur.when || T.since(cur.ms)) + (cur.took !== undefined ? ' · ' + cur.took + ' ms' : '')));
  box.textContent = '';
  // A newly chosen block shows its calls one after the other.
  box.classList.toggle('anim', T.shown !== key);
  T.shown = key;
  box.appendChild(el('p', 'tl-text', cur.text));
  if (d.tab === 'state') T.drawChanges(box);
  else {
    box.appendChild(el('div', 'tl-detail-sub', 'What happens inside this block'));
    const inside = el('div', 'tl-inside');
    T.drawDetails(inside);
    box.appendChild(inside);
  }
  box.scrollTop = keep;
}

