      }
      cm.setValue(text);
      cm.clearHistory();
      if (keep.length) {
        let sp = {};
        try { sp = core.spans(text); } catch (e) {}
        cm.operation(() => keep.forEach(k => { const r = sp[k]; if (r && r.obj) cm.foldCode(CodeMirror.Pos(cm.posFromIndex(r.start).line, 0), { rangeFinder: CodeMirror.fold.brace, widget: '…' }, 'fold'); }));
